"""billing-service entry point."""

from billing.metering import MeteringAggregator
from billing.scheduler import PaymentScheduler


def create_app(config):
    aggregator = MeteringAggregator(
        window_minutes=config.get("metering_window_minutes", 5),
        rounding_mode=config.get("rounding_mode", "half_up"),
    )
    scheduler = PaymentScheduler(
        max_retries=config.get("payment_max_retries", 3),
        backoff_base_seconds=config.get("payment_backoff_base_seconds", 30),
    )
    return {
        "aggregator": aggregator,
        "scheduler": scheduler,
    }

"""Usage metering aggregation."""

from decimal import Decimal, ROUND_HALF_UP


class MeteringAggregator:
    def __init__(self, window_minutes=5, rounding_mode="half_up"):
        self.window_minutes = window_minutes
        self.rounding_mode = rounding_mode

    def aggregate(self, samples):
        """Sum usage samples into a billable quantity.

        Rounding is applied once at the end of the window to avoid the
        cumulative drift we saw when rounding per-sample (fixed in 2.4.1-dev).
        """
        total = sum(Decimal(str(s.quantity)) for s in samples)
        if self.rounding_mode == "half_up":
            return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        return total
